'use client'

import Link from 'next/link'

import { useListPersona } from '@/hooks/use-list-persona'
import { featureFlags } from '@/lib/feature-flags'

/**
 * An AI expert's list says it was made by AI (spec-ai-expert-personas.md, UI
 * requirement 4) — the share page's footer, in the phone's language: the AI
 * chip (Home's), then "Generated by FieldScout AI as <name> — a fictional,
 * parody analyst persona not affiliated with any real person." The name links
 * to the expert's page while that surface is on. Until the name has been read
 * (or if it can't be), the line still says the list is AI-made; a switched-off
 * expert's list has no line, as on the share page.
 *
 * Under the players on both phone screens that show one list: the List view
 * and Community's list page (audit lists-2 — a shared AI expert's list opens
 * on either, `inAppListHref`).
 */
export function ListAiAttribution({ personaId }: { personaId: string }) {
  const persona = useListPersona(personaId)
  if (persona.data === null) return null
  const p = persona.data
  return (
    <p
      className="px-4 pb-6 text-center text-[11px] font-medium leading-[1.5] text-m-t3 [text-wrap:pretty]"
      data-list-ai-attribution
    >
      <span className="mr-1.5 inline-flex h-5 items-center rounded-pill bg-m-b2 px-2 align-middle text-[10px] font-semibold">
        AI
      </span>
      Generated by FieldScout AI
      {p ? (
        <>
          {' as '}
          {featureFlags.personas ? (
            <Link href={`/personas/${encodeURIComponent(p.username)}`} className="font-semibold text-m-t1">
              {p.display_name}
            </Link>
          ) : (
            <span className="font-semibold text-m-t1">{p.display_name}</span>
          )}
          {' — a fictional, parody analyst persona not affiliated with any real person.'}
        </>
      ) : (
        '.'
      )}
    </p>
  )
}
